package simulator

const indexHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>DBFabric Control Room</title>
<style>
:root{--ink:#e7edf2;--muted:#8b9aa7;--bg:#10161b;--panel:#182229;--line:#2b3a43;--cyan:#66d9d0;--coral:#ff8e78;--green:#8be0a1;--mono:"Cascadia Code",Consolas,monospace;--display:"Trebuchet MS",sans-serif}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% -10%,#203844 0,#10161b 42%);color:var(--ink);font:14px/1.5 var(--display)}main{max-width:1380px;margin:auto;padding:38px 34px 60px}.top{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;border-bottom:1px solid var(--line);padding-bottom:24px}.eyebrow{color:var(--cyan);font:11px var(--mono);letter-spacing:2px;text-transform:uppercase}.title{font-size:clamp(30px,4vw,54px);font-weight:700;letter-spacing:0;margin:4px 0 0}.subtitle{color:var(--muted);max-width:520px;margin:8px 0 0}.badge{border:1px solid #38605f;color:var(--cyan);padding:8px 12px;font:12px var(--mono);white-space:nowrap}.layout{display:grid;grid-template-columns:minmax(0,1fr) 370px;gap:18px;margin-top:22px}.panel{background:rgba(24,34,41,.88);border:1px solid var(--line);padding:20px}.panel h2{font-size:17px;margin:0 0 4px}.panel-note{color:var(--muted);font-size:12px;margin:0 0 18px}.shards{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:12px}.shard{border:1px solid var(--line);background:#141d23}.shard-head{display:flex;justify-content:space-between;padding:13px 15px;border-bottom:1px solid var(--line)}.shard-id{font:13px var(--mono);color:var(--cyan)}.node{display:grid;grid-template-columns:8px 1fr auto;gap:10px;align-items:center;padding:12px 15px;border-bottom:1px solid #223038}.node:last-child{border:0}.dot{width:8px;height:8px;background:var(--green);border-radius:50%;box-shadow:0 0 10px var(--green)}.dot.down{background:var(--coral);box-shadow:0 0 10px var(--coral)}.node-main{min-width:0}.addr{display:block;font:12px var(--mono);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.role{color:var(--muted);font-size:11px}.meta{text-align:right;color:var(--muted);font:11px var(--mono)}button{border:1px solid #45616b;background:#1b2b32;color:var(--ink);padding:6px 9px;cursor:pointer;font:11px var(--mono)}button:hover{border-color:var(--cyan);color:var(--cyan)}.node-actions{display:flex;gap:5px;margin-top:5px;justify-content:flex-end}.controls{display:grid;gap:14px}.field{display:grid;gap:6px}.field label{color:var(--muted);font-size:12px}.field input,.field select{width:100%;background:#10181d;border:1px solid var(--line);color:var(--ink);padding:10px;font:13px var(--mono)}.route-btn{background:var(--cyan);color:#102124;border:0;padding:12px;font-weight:bold}.route-btn:hover{color:#102124;background:#9be9e1}.route-result{min-height:68px;border-left:3px solid var(--cyan);background:#112026;padding:11px 13px;font:12px var(--mono);white-space:pre-wrap}.route-result.error{border-color:var(--coral);color:var(--coral)}.events{margin-top:18px}.event{padding:9px 0;border-bottom:1px solid #25343c;color:var(--muted);font:11px var(--mono)}.empty{color:var(--muted);font-size:12px}@media(max-width:900px){main{padding:25px 16px}.top{display:block}.badge{display:inline-block;margin-top:16px}.layout{grid-template-columns:1fr}.shards{grid-template-columns:1fr}}
</style></head><body><main>
<header class="top"><div><div class="eyebrow">DBFabric / control room</div><h1 class="title">Routing under pressure.</h1><p class="subtitle">Exercise shard placement, replica lag, consistency policy, and failover decisions against the real router.</p></div><div class="badge" id="listen">loading topology...</div></header>
<div class="layout"><section class="panel"><h2>Shard topology</h2><p class="panel-note">Toggle a node to simulate a hard failure. Promote chooses the least-lagged healthy replica.</p><div id="shards" class="shards"></div><div class="events"><h2>Event stream</h2><div id="events" class="empty">No interventions yet.</div></div></section>
<aside class="panel"><h2>Route a request</h2><p class="panel-note">This calls the same consistent-hash router used by the proxy.</p><div class="controls"><div class="field"><label for="key">Shard key</label><input id="key" value="user-42"></div><div class="field"><label for="consistency">Consistency</label><select id="consistency"><option value="strong">Strong / primary</option><option value="eventual">Eventual / replica</option><option value="bounded_staleness">Bounded staleness</option></select></div><div class="field"><label for="lag">Maximum lag (ms)</label><input id="lag" type="number" min="0" value="1000"></div><button class="route-btn" onclick="route()">Resolve route</button><div id="result" class="route-result">Choose a policy and resolve a request.</div></div></aside></div></main>
<script>
const $=id=>document.getElementById(id);let state;
async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body&&JSON.stringify(body)});return r.json()}
async function refresh(){state=await api('/api/state');$('listen').textContent='PROXY '+state.listen_addr+'  /  UI ONLINE';$('lag').value=state.max_lag_ms;render()}
function render(){ $('shards').innerHTML=state.shards.map(function(s){var nodes=[Object.assign({},s.primary,{role:'PRIMARY'})].concat(s.replicas.map(function(n){return Object.assign({},n,{role:'REPLICA'})}));var html='<article class="shard"><div class="shard-head"><span class="shard-id">'+s.id+'</span><button onclick="promote(\''+s.id+'\')">Promote replica</button></div>';html+=nodes.map(function(n){var lagButton=n.role==='REPLICA'?'<div class="node-actions"><button onclick="lag(\''+s.id+'\',\''+n.addr+'\','+n.lag_ms+')">Set lag</button></div>':'';return '<div class="node"><i class="dot '+(n.status==='DOWN'?'down':'')+'"></i><div class="node-main"><span class="addr">'+n.addr+'</span><span class="role">'+n.role+' - '+n.status+'</span>'+lagButton+'</div><div class="meta">'+(n.role==='REPLICA'?n.lag_ms+' ms':'write path')+'<br><button onclick="toggle(\''+s.id+'\',\''+n.addr+'\')">'+(n.status==='DOWN'?'recover':'fail')+'</button></div></div>'}).join('');return html+'</article>'}).join('');$('events').innerHTML=state.events.length?state.events.map(function(e){return '<div class="event">'+e+'</div>'}).join(''):'<span class="empty">No interventions yet.</span>' }
async function action(body){const result=await api('/api/simulate',body);if(result.error){alert(result.error);return}state=result;render()}
function toggle(shard,node){action({action:'toggle',shard,node})}function promote(shard){action({action:'promote',shard})}function lag(shard,node,current){const value=prompt('Replica lag in milliseconds',current);if(value!==null)action({action:'lag',shard,node,lag_ms:Number(value)})}
async function route(){const result=await api('/api/route',{shard_key:$('key').value,consistency:$('consistency').value,max_lag_ms:Number($('lag').value)});const box=$('result');if(result.error){box.className='route-result error';box.textContent=result.error;return}box.className='route-result';box.textContent=result.consistency.toUpperCase()+'\n'+result.shard_id+'  ->  '+result.node+'\n'+result.role+' - '+result.status+' - '+result.lag_ms+'ms'}
refresh();
</script></body></html>`
